import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"法律条文索引","description":"","frontmatter":{},"headers":[],"relativePath":"zh/92-法律条文索引.md","filePath":"zh/92-法律条文索引.md","lastUpdated":1789183869000}'),h={name:"zh/92-法律条文索引.md"};function o(l,t,i,b,n,s){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="法律条文索引" tabindex="-1">法律条文索引 <a class="header-anchor" href="#法律条文索引" aria-label="Permalink to &quot;法律条文索引&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>92</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>法律索引、共生宪法、劳动法、消保法、配套法</td></tr></tbody></table><h2 id="一、索引说明" tabindex="-1">一、索引说明 <a class="header-anchor" href="#一、索引说明" aria-label="Permalink to &quot;一、索引说明&quot;">​</a></h2><p>本索引收录锚点共生文明现行有效的主要法律文件及其核心条文，按法律层级与部门分类编排。索引范围涵盖《共生宪法》、《共生劳动法》、《消费者保护法》以及教育、医疗、住房、环境、反垄断五部配套法。每条索引列出法律名称、条文编号与条文核心内容摘要。本索引为查阅工具，法律条文的完整文本与司法解释参见各法律的官方文本。</p><h2 id="二、共生宪法" tabindex="-1">二、共生宪法 <a class="header-anchor" href="#二、共生宪法" aria-label="Permalink to &quot;二、共生宪法&quot;">​</a></h2><p>《共生宪法》是锚点共生文明的根本大法，具有最高法律效力，于共生文明正式建立之际制定。</p><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>确立衡元宙（万灵衡锚本源宙）为锚点共生文明的治理全域，共生文明的根本宗旨是实现万族共生、宇宙升维</td></tr><tr><td>第二条</td><td>确立反掠夺主义为文明根本立场，禁止任何形式的掠夺式修炼与资源掠夺</td></tr><tr><td>第三条</td><td>确立&quot;将命运与进化的选择权交还给众生&quot;为文明核心理念</td></tr><tr><td>第四条</td><td>确立多劳多得、自生自长、人人有路、万族共进为文明基本方针</td></tr><tr><td>第五条</td><td>确立三百套本源修炼体系免费开放制度，任何组织和个人不得垄断修炼体系的传授权</td></tr><tr><td>第六条</td><td>确立联产承包机制为基本资源分配制度</td></tr><tr><td>第七条</td><td>确立20%激活战略为阶段性国家目标</td></tr><tr><td>第八条</td><td>确立现实为基原则，现实世界是唯一真实世界，虚构设定不具有法律效力</td></tr><tr><td>第九条</td><td>确立四阶段升维路径为文明长期发展战略</td></tr><tr><td>第十条</td><td>确立万族平等原则，一切生命形态在法律面前一律平等</td></tr><tr><td>第十一条</td><td>确立共生进化原则，个体进化不得以损害其他个体或集体的进化权利为代价</td></tr><tr><td>第十二条</td><td>确立多劳多得原则，资源分配以贡献为核心依据</td></tr><tr><td>第十三条</td><td>确立自生自长原则，尊重每个生命的自主进化选择权</td></tr><tr><td>第十四条</td><td>真立人人有路原则，国家有义务为每个生命提供基本的进化路径与资源保障</td></tr><tr><td>第十五条</td><td>确立可持续原则，一切发展必须兼顾宇宙本源的可持续性</td></tr><tr><td>第十六条至第二十五条</td><td>规定众生的基本权利：进化选择权、修炼资源获取权、平等保护权、共生参与权、文化保留权、救济申诉权、人身自由权、人格尊严权、信仰自由权、表达自由权</td></tr><tr><td>第二十六条至第三十一条</td><td>规定众生的基本义务：守法义务、维护共生秩序义务、劳动贡献义务、保护环境义务、尊重他人权利义务、指导初级修炼者义务</td></tr><tr><td>第三十二条</td><td>确立锚点议事会为最高权力机构，由万族代表按比例组成</td></tr><tr><td>第三十三条</td><td>确立共生执行委员会为最高行政机构</td></tr><tr><td>第三十四条</td><td>确立共生法院为最高司法机构，独立行使审判权</td></tr><tr><td>第三十五条</td><td>确立锚点监督委员会为独立监督机构</td></tr><tr><td>第三十六条</td><td>规定立法程序：法律案由锚点议事会半数以上多数通过</td></tr><tr><td>第三十七条</td><td>规定宪法修改程序：须经锚点议事会三分之二以上多数通过并经全民公投半数以上同意</td></tr><tr><td>第三十八条</td><td>确立违宪审查制度，共生法院有权宣布违反宪法的法律无效</td></tr><tr><td>第三十九条</td><td>确立宪法诉讼制度，众生可以直接依据宪法提起诉讼</td></tr><tr><td>第四十条</td><td>规定地方自治制度，各星域、各位面在宪法框架内实行自治</td></tr><tr><td>第四十一条</td><td>确立万族共和制度，各民族在共生文明中一律平等，实行区域自治</td></tr><tr><td>第四十二条</td><td>规定共生文明的经济制度：以联产承包为基础，多种所有制经济共同发展</td></tr><tr><td>第四十三条</td><td>规定修炼资源的国家所有与公平分配制度</td></tr><tr><td>第四十四条</td><td>确立教育公平制度，保障每个生命平等的受教育权</td></tr><tr><td>第四十五条</td><td>确立全民医疗保障制度</td></tr><tr><td>第四十六条</td><td>确立住房保障制度，保障每个生命的基本居住权</td></tr><tr><td>第四十七条</td><td>规定跨位面交互的基本原则，未经许可不得擅自进行跨位面穿梭</td></tr><tr><td>第四十八条</td><td>规定考古活动的合法产出仅限于抽象知识与信息，禁止回传物质与能量</td></tr><tr><td>第四十九条</td><td>规定时间回溯的基本原则，必须遵循先观测后有限干涉</td></tr><tr><td>第五十条</td><td>规定宪法的解释权属于共生法院，宪法的修改权属于锚点议事会</td></tr></tbody></table><h2 id="三、共生劳动法" tabindex="-1">三、共生劳动法 <a class="header-anchor" href="#三、共生劳动法" aria-label="Permalink to &quot;三、共生劳动法&quot;">​</a></h2><p>《共生劳动法》是规范劳动关系、保障劳动者权益的基本法律，以共生宪法第四十二条为立法依据。</p><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：规范劳动关系，保护劳动者合法权益，构建和谐共生的劳动关系</td></tr><tr><td>第二条</td><td>适用范围：衡元宙内一切劳动关系，包括物质劳动、修炼劳动与创造性劳动</td></tr><tr><td>第三条</td><td>确立劳动者平等就业原则，禁止基于种族、性别、修为、出身的就业歧视</td></tr><tr><td>第四条</td><td>确立劳动者自由择业原则，禁止强制劳动与奴役</td></tr><tr><td>第五条</td><td>规定劳动合同制度，建立劳动关系应当订立书面劳动合同</td></tr><tr><td>第六条</td><td>规定劳动合同的必备条款：合同期限、工作内容、劳动报酬、工作时间、劳动保护、社会保险</td></tr><tr><td>第七条</td><td>确立八小时工作制与每周不超过四十四小时的工时制度</td></tr><tr><td>第八条</td><td>规定加班限制：每日加班不超过一小时，特殊情况不超过三小时，每月不超过三十六小时</td></tr><tr><td>第九条</td><td>规定加班工资标准：工作日加班1.5倍工资，休息日加班2倍工资，法定节假日加班3倍工资</td></tr><tr><td>第十条</td><td>确立最低工资保障制度，最低工资标准由各星域根据当地情况制定</td></tr><tr><td>第十一条</td><td>规定工资支付制度：工资应当以货币形式按月支付给劳动者本人，不得克扣或无故拖欠</td></tr><tr><td>第十二条</td><td>确立多劳多得的分配原则，实行按劳分配为主体、多种分配方式并存的分配制度</td></tr><tr><td>第十三条</td><td>规定劳动安全卫生制度，用人单位必须为劳动者提供符合标准的劳动安全卫生条件</td></tr><tr><td>第十四条</td><td>规定特殊群体保护：对未成年劳动者、女性劳动者、残疾劳动者、低修为劳动者实行特殊劳动保护</td></tr><tr><td>第十五条</td><td>确立职业培训制度，用人单位有义务对劳动者进行职业技能培训</td></tr><tr><td>第十六条</td><td>规定修炼者的劳动权益：修炼劳动同样受本法保护，修炼成果的归属由合同约定</td></tr><tr><td>第十七条</td><td>确立劳动者社会保险制度：养老保险、医疗保险、失业保险、工伤保险、生育保险</td></tr><tr><td>第十八条</td><td>规定劳动者福利制度：用人单位应当为劳动者提供必要的福利待遇</td></tr><tr><td>第十九条</td><td>确立劳动争议处理制度：协商、调解、仲裁、诉讼四级处理机制</td></tr><tr><td>第二十条</td><td>规定工会制度，劳动者有权依法组织和参加工会，维护自身合法权益</td></tr><tr><td>第二十一条</td><td>规定集体合同制度，工会代表职工与用人单位订立集体合同</td></tr><tr><td>第二十二条</td><td>规定用人单位的规章制度应当经职工代表大会或全体职工讨论</td></tr><tr><td>第二十三条</td><td>规定劳动合同的解除条件与程序</td></tr><tr><td>第二十四条</td><td>规定经济补偿金制度，用人单位依法解除劳动合同应当支付经济补偿</td></tr><tr><td>第二十五条</td><td>规定违法解除劳动合同的赔偿金制度</td></tr><tr><td>第二十六条</td><td>确立劳务派遣管理制度，规范劳务派遣用工</td></tr><tr><td>第二十七条</td><td>规定非全日制用工的特殊规则</td></tr><tr><td>第二十八条</td><td>规定监督检查制度，劳动行政部门依法对用人单位遵守劳动法律法规的情况进行监督检查</td></tr><tr><td>第二十九条</td><td>规定法律责任：用人单位违反本法的，依法承担行政责任、民事责任与刑事责任</td></tr><tr><td>第三十条</td><td>规定本法的施行日期与解释权</td></tr></tbody></table><h2 id="四、消费者保护法" tabindex="-1">四、消费者保护法 <a class="header-anchor" href="#四、消费者保护法" aria-label="Permalink to &quot;四、消费者保护法&quot;">​</a></h2><p>《消费者保护法》是保护消费者合法权益、规范经营者行为的基本法律。</p><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：保护消费者合法权益，维护社会经济秩序，促进共生市场经济健康发展</td></tr><tr><td>第二条</td><td>适用范围：衡元宙内消费者为生活消费需要购买、使用商品或接受服务的权益保护</td></tr><tr><td>第三条</td><td>确立经营者与消费者交易的基本原则：自愿、平等、公平、诚实信用</td></tr><tr><td>第四条</td><td>确立国家保护消费者合法权益的原则，国家采取措施保障消费者依法行使权利</td></tr><tr><td>第五条</td><td>规定消费者的九项基本权利：安全权、知情权、自主选择权、公平交易权、求偿权、结社权、获得知识权、受尊重权、监督权</td></tr><tr><td>第六条</td><td>规定消费者安全权：消费者在购买、使用商品和接受服务时享有人身、财产安全不受损害的权利</td></tr><tr><td>第七条</td><td>规定消费者知情权：消费者享有知悉其购买、使用的商品或接受的服务的真实情况的权利</td></tr><tr><td>第八条</td><td>规定消费者自主选择权：消费者享有自主选择商品或服务的权利</td></tr><tr><td>第九条</td><td>规定消费者公平交易权：消费者享有公平交易的权利，有权拒绝强制交易行为</td></tr><tr><td>第十条</td><td>规定消费者求偿权：消费者因购买、使用商品或接受服务受到人身、财产损害的，享有依法获得赔偿的权利</td></tr><tr><td>第十一条</td><td>规定经营者的基本义务：履行法定与约定义务、接受监督、保障安全、提供真实信息、出具凭证、保证质量、履行三包、不得不公平交易、不得侵犯人格</td></tr><tr><td>第十二条</td><td>规定经营者安全保障义务：经营者应当保证其提供的商品或服务符合保障人身、财产安全的要求</td></tr><tr><td>第十三条</td><td>规定经营者信息披露义务：经营者应当向消费者提供有关商品或服务的真实信息，不得作虚假或引人误解的宣传</td></tr><tr><td>第十四条</td><td>规定修炼产品与服务的特殊规范：修炼法门、修炼器械、能量产品的经营者须具备特殊资质，产品须经过安全认证</td></tr><tr><td>第十五条</td><td>规定格式条款的规制：经营者不得以格式条款排除或限制消费者权利、减轻或免除经营者责任</td></tr><tr><td>第十六条</td><td>规定七天无理由退货制度：消费者通过网络等远程方式购买商品的，有权自收到商品之日起七日内退货</td></tr><tr><td>第十七条</td><td>规定三包制度：经营者提供的商品或服务不符合质量要求的，消费者可以依照国家规定要求修理、更换、退货</td></tr><tr><td>第十八条</td><td>规定惩罚性赔偿制度：经营者提供商品或服务有欺诈行为的，应当按照消费者要求增加赔偿其受到的损失，增加赔偿金额为消费者购买商品价款或接受服务费用的三倍</td></tr><tr><td>第十九条</td><td>规定消费者组织：消费者协会和其他消费者组织是依法成立的对商品和服务进行社会监督的保护消费者合法权益的社会组织</td></tr><tr><td>第二十条</td><td>规定消费争议解决途径：与经营者协商和解、请求消费者协会调解、向有关行政部门申诉、提请仲裁、向法院提起诉讼</td></tr><tr><td>第二十一条</td><td>规定争议举证责任倒置：对于耐用商品或装饰装修等服务，消费者自接受之日起六个月内发现瑕疵，由经营者承担举证责任</td></tr><tr><td>第二十二条</td><td>规定经营者的行政责任与刑事责任</td></tr><tr><td>第二十三条</td><td>规定本法的施行日期与解释权</td></tr></tbody></table><h2 id="五、五部配套法" tabindex="-1">五、五部配套法 <a class="header-anchor" href="#五、五部配套法" aria-label="Permalink to &quot;五、五部配套法&quot;">​</a></h2><h3 id="_5-1-教育保障法" tabindex="-1">5.1 教育保障法 <a class="header-anchor" href="#_5-1-教育保障法" aria-label="Permalink to &quot;5.1 教育保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：保障众生平等的受教育权，构建共生教育体系，促进万族文化共同发展</td></tr><tr><td>第二条至第五条</td><td>确立教育公平原则、教育免费原则（基础教育阶段）、教育多元原则、教育创新原则</td></tr><tr><td>第六条至第十条</td><td>规定学前教育、义务教育、高中阶段教育、高等教育、修炼教育的体系架构</td></tr><tr><td>第十一条至第十五条</td><td>规定修炼教育的特殊制度：三百套体系的教学规范、导师制度、修炼资源配给制度</td></tr><tr><td>第十六条至第二十条</td><td>规定教师权利义务、教师资格制度、教师待遇保障</td></tr><tr><td>第二十一条至第二十五条</td><td>规定教育投入保障、教育设施建设、教育信息化、特殊教育、跨种族教育</td></tr><tr><td>第二十六条至第三十条</td><td>规定教育评估制度、教育监督制度、法律责任与附则</td></tr></tbody></table><h3 id="_5-2-医疗保障法" tabindex="-1">5.2 医疗保障法 <a class="header-anchor" href="#_5-2-医疗保障法" aria-label="Permalink to &quot;5.2 医疗保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：建立全民医疗保障体系，保障众生的健康权，提升万族整体健康水平</td></tr><tr><td>第二条至第五条</td><td>确立全民医保原则、基本医疗免费原则、中西医结合原则、修炼医疗纳入原则</td></tr><tr><td>第六条至第十条</td><td>规定基本医疗保险、大病保险、医疗救助、商业健康保险的多层次医保体系</td></tr><tr><td>第十一条至第十五条</td><td>规定医疗机构管理、医护人员制度、医疗质量安全、修炼医疗的特殊规范</td></tr><tr><td>第十六条至第二十条</td><td>规定药品管理、医疗器械管理、能量医疗产品管理、基本药物制度</td></tr><tr><td>第二十一条至第二十五条</td><td>规定公共卫生体系、疾病预防控制、健康教育、跨种族医疗、特殊群体医疗保障</td></tr><tr><td>第二十六条至第三十条</td><td>规定医疗纠纷处理、医疗监督、法律责任与附则</td></tr></tbody></table><h3 id="_5-3-住房保障法" tabindex="-1">5.3 住房保障法 <a class="header-anchor" href="#_5-3-住房保障法" aria-label="Permalink to &quot;5.3 住房保障法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：保障众生的基本居住权，构建多层次住房保障体系，实现住有所居</td></tr><tr><td>第二条至第五条</td><td>确立居住权保障原则、住房公平原则、租购并举原则、可持续住房原则</td></tr><tr><td>第六条至第十条</td><td>规定公共租赁住房、保障性租赁住房、共有产权住房、商品住房的住房供应体系</td></tr><tr><td>第十一条至第十五条</td><td>规定住房公积金制度、住房补贴制度、首套房支持政策、修炼者特殊住房政策</td></tr><tr><td>第十六条至第二十条</td><td>规定住房建设标准、空间技术在住房中的应用、绿色建筑、适老化与无障碍住房</td></tr><tr><td>第二十一条至第二十五条</td><td>规定房地产市场调控、住房租赁市场规范、物业服务管理、住房维修保障</td></tr><tr><td>第二十六条至第三十条</td><td>规定住房保障监督、法律责任与附则</td></tr></tbody></table><h3 id="_5-4-环境保护法" tabindex="-1">5.4 环境保护法 <a class="header-anchor" href="#_5-4-环境保护法" aria-label="Permalink to &quot;5.4 环境保护法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：保护和改善环境，防治污染和其他公害，保障公众健康，推进宇宙生态文明建设，促进可持续发展</td></tr><tr><td>第二条至第五条</td><td>确立保护优先原则、预防为主原则、综合治理原则、公众参与原则、损害担责原则</td></tr><tr><td>第六条至第十条</td><td>规定环境监督管理体制、环境标准制度、环境影响评价制度、环境监测制度、跨位面环境管理</td></tr><tr><td>第十一条至第十五条</td><td>规定大气污染防治、水污染防治、土壤污染防治、能量污染防治、法则污染防治</td></tr><tr><td>第十六条至第二十条</td><td>规定固体废物处理、噪声污染防治、放射性污染防治、生态保护、生物多样性保护</td></tr><tr><td>第二十一条至第二十五条</td><td>规定修炼活动的环境影响管控、能量开采的生态保护、跨位面考古的环境要求</td></tr><tr><td>第二十六条至第三十条</td><td>规定信息公开与公众参与、环境公益诉讼、法律责任与附则</td></tr></tbody></table><h3 id="_5-5-反垄断法" tabindex="-1">5.5 反垄断法 <a class="header-anchor" href="#_5-5-反垄断法" aria-label="Permalink to &quot;5.5 反垄断法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条文编号</th><th>核心内容</th></tr></thead><tbody><tr><td>第一条</td><td>立法目的：预防和制止垄断行为，保护市场公平竞争，提高经济运行效率，维护消费者利益和社会公共利益，促进共生市场经济健康发展</td></tr><tr><td>第二条至第五条</td><td>确立竞争政策基础性地位、公平竞争审查制度、禁止垄断协议、禁止滥用市场支配地位、控制经营者集中</td></tr><tr><td>第六条至第十条</td><td>规定垄断协议的认定与豁免、横向垄断协议、纵向垄断协议、行业协会垄断行为</td></tr><tr><td>第十一条至第十五条</td><td>规定市场支配地位的认定、滥用市场支配地位的行为类型、掠夺性定价的禁止</td></tr><tr><td>第十六条至第二十条</td><td>规定经营者集中申报标准、审查程序、附加限制性条件、禁止集中的决定</td></tr><tr><td>第二十一条至第二十五条</td><td>规定修炼体系垄断的特殊禁止：禁止垄断修炼法门、禁止修炼资源垄断、禁止导师网络垄断</td></tr><tr><td>第二十六条至第三十条</td><td>规定反垄断执法机构、调查程序、法律责任、宽恕制度与附则</td></tr></tbody></table><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>法律条文索引是锚点共生文明法治体系的查阅地图。从作为根本大法的共生宪法，到规范民生的劳动法与消保法，再到五部配套法，共同构成了&quot;以宪法为统帅、以基本法为主干、以配套法为支撑&quot;的完整法律体系。这一体系确保了共生文明的一切活动都在法治轨道上运行，为万族共进提供了坚实的制度保障。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>40-共生宪法总纲</li><li>41-共生劳动法</li><li>48-司法体系与裁决机制</li></ul>',28)])])}const u=d(h,[["render",o]]);export{_ as __pageData,u as default};
